const c = await api.get("/customers");
const m = await api.get("/mails", { label: "complaint" });
const delayed = c.items.filter(x => x.order && x.order.status === "delayed").map(x => x.id);
const complainers = new Set(m.items.filter(x => x.label === "complaint" && x.customer_id).map(x => x.customer_id));
const result = delayed.filter(id => complainers.has(id));
return { customers_total: c.count, customers_fetched: c.items.length, mails_total: m.count, mails_fetched: m.items.length, delayed_count: delayed.length, matched_ids: result };
